import{_ as a,o as s,c as i,ag as t}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"背包查询与材质配置","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/inventory.md","filePath":"shitbot/inventory.md"}'),n={name:"shitbot/inventory.md"};function l(o,e,d,p,c,r){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="背包查询与材质配置" tabindex="-1">背包查询与材质配置 <a class="header-anchor" href="#背包查询与材质配置" aria-label="Permalink to &quot;背包查询与材质配置&quot;">​</a></h1><h2 id="开启背包查询" tabindex="-1">开启背包查询 <a class="header-anchor" href="#开启背包查询" aria-label="Permalink to &quot;开启背包查询&quot;">​</a></h2><p>在 <code>config.yml</code> 中确认：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">onebot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;default&quot;</span></span></code></pre></div><p>保存后执行 <code>/shitbot reload</code>。Spigot 和 Nukkit-MOT 会定时保存在线玩家背包，并在玩家退出时再保存一次。</p><p>命令别名和回复文本在所选 <code>lang/*.yml</code> 的 <code>commands.inventory</code> 与 <code>messages</code> 下修改。背包图片外观在 <code>templates/*.yml</code> 的 <code>inventory</code> 段修改；复制默认模板并通过 <code>inventory.template</code> 选择，详细格式见<a href="./configuration.html#自定义图片模板">配置说明</a>。</p><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><p>群成员可以发送 <code>背包</code> 或 <code>我的背包</code>，让系统从自己 QQ 已绑定的角色中自动选择一个查询；命令别名可在语言文件中修改。</p><p>群成员有多个游戏 ID 时，可发送 <code>背包 &lt;游戏ID&gt;</code> 或 <code>我的背包 &lt;游戏ID&gt;</code> 自由查询其中任意一个。系统会先精确校验该游戏 ID 是否绑定到消息发送者的 QQ，只有校验通过才会读取并发送背包图片，不能借此查询他人的角色。</p><h2 id="支持离线查询" tabindex="-1">支持离线查询 <a class="header-anchor" href="#支持离线查询" aria-label="Permalink to &quot;支持离线查询&quot;">​</a></h2><p>默认每 60 秒保存一次在线玩家快照，玩家退出时也会立即保存。快照默认保留 30 天，因此玩家离线后仍可从 QQ 查询最近一次背包。</p><p>玩家从未进入过启用背包快照的服务端、快照已经过期或 <code>inventory.enabled</code> 被关闭时，机器人会返回暂无快照。历史旧格式快照缺少的新字段，需要玩家重新上线后才会补齐。</p><h2 id="群组服部署" tabindex="-1">群组服部署 <a class="header-anchor" href="#群组服部署" aria-label="Permalink to &quot;群组服部署&quot;">​</a></h2><p>代理端没有玩家背包。群组服请让代理端与所有后端 Spigot 使用同一个 MySQL 数据库：</p><ul><li>后端 Spigot 可关闭 <code>onebot.enabled</code>，但保留 <code>inventory.enabled</code>，负责定时和退出快照；</li><li>BungeeCord/Velocity 负责接收 QQ 命令、读取共享快照和生成图片；</li><li>SQLite 只适合单服，不能作为多进程共享数据库。</li></ul><p>代理端生成图片时也必须能访问同一套物品资源。可把客户端核心、资源包和 Mod JAR 放在代理可访问的位置，并在 <code>resource-archives</code> 中写绝对路径；也可以复制精确导出的 <code>item-icons</code>。</p><h2 id="跨版本材质解析" tabindex="-1">跨版本材质解析 <a class="header-anchor" href="#跨版本材质解析" aria-label="Permalink to &quot;跨版本材质解析&quot;">​</a></h2><p>解析优先级：</p><ol><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;__cmd_&lt;custom-model-data&gt;.png</code>；</li><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;__data_&lt;旧版数据值&gt;.png</code>；</li><li><code>item-icons/&lt;namespace&gt;/&lt;path&gt;.png</code>；</li><li><code>inventory.icons.resource-archives</code> 中显式配置的目录、资源包、客户端核心或资源 JAR；</li><li>自动发现的 <code>resources</code>、<code>resourcepacks</code>、<code>server-resource-packs</code>、<code>mods</code>、<code>versions</code> 和客户端 JAR。</li></ol><p>ShitBot 的 Spigot 运行兼容线从 1.8.8 开始；材质解析器覆盖 1.8.8 到当前 26.x 使用过的资源格式，并兼容旧资源包中的直接贴图目录：</p><ul><li>旧资源包的 <code>textures/items</code>、<code>textures/blocks</code> 直接贴图；</li><li>1.8 起的 JSON 物品和方块模型，包括旧版 <code>builtin/generated</code> / <code>builtin/handheld</code>；</li><li>1.8-1.12 Bukkit 材质名、旧注册名和 data value 变种；</li><li>1.13 扁平化后的命名空间物品 ID；</li><li>传统模型 <code>overrides</code> 中的 <code>custom_model_data</code>、<code>damage</code> 和 <code>damaged</code>；</li><li>1.21.4 到 26.x 的 <code>assets/&lt;namespace&gt;/items/*.json</code>：model、composite、condition、range_dispatch、select 和 special 基础模型；</li><li>新版 CustomModelData 的 floats、flags、strings、colors 有界快照；</li><li>1.8 到当前版本的 GameProfile、PlayerProfile 和 ResolvableProfile 玩家头贴图。</li></ul><p>普通二维物品会合成全部 <code>layer0...layer15</code>。普通方块模型会从继承后的 top/side/face 材质生成等距图标。动画 PNG 使用第一帧，避免整条动画被压缩到一个格子里。</p><h3 id="客户端核心放在哪里" tabindex="-1">客户端核心放在哪里 <a class="header-anchor" href="#客户端核心放在哪里" aria-label="Permalink to &quot;客户端核心放在哪里&quot;">​</a></h3><p>ShitBot 不携带 Mojang 原版材质。要显示原版物品，运行图片渲染的一端必须能读取对应版本的客户端核心或完整原版资源包。</p><p>单服默认目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server/</span></span>
<span class="line"><span>├─ mods/</span></span>
<span class="line"><span>│  └─ 1.8.9-client.jar</span></span>
<span class="line"><span>└─ plugins/ShitBot/</span></span></code></pre></div><p>默认 <code>mods-directory: ../../mods</code> 会从 <code>plugins/ShitBot</code> 解析到上面的 <code>server/mods</code>。文件必须是包含 <code>assets/minecraft</code> 的客户端 JAR；Forge/OptiFine 安装器、启动器核心或只有 class 的裁剪包不能代替客户端资源。</p><p>也可显式配置，优先级更清楚：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inventory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  icons</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    resource-archives</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/Minecraft/versions/1.8.9/1.8.9.jar&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/Minecraft/resourcepacks/server-pack.zip&quot;</span></span></code></pre></div><p>资源索引启动时异步建立；首次查询最多等待 <code>index-wait-ms</code>。每隔 <code>refresh-seconds</code> 检查文件时间和大小，新增或替换 JAR 后无需因负缓存永久显示缺失材质。</p><h3 id="玩家头" tabindex="-1">玩家头 <a class="header-anchor" href="#玩家头" aria-label="Permalink to &quot;玩家头&quot;">​</a></h3><p>Spigot 后端会兼容读取旧版 CraftMetaSkull/GameProfile、新版 PlayerProfile/ResolvableProfile 中的 <code>textures</code> 属性，只截取并保存 <code>textures.minecraft.net</code> 的十六进制内容哈希。图片端通过固定的 Mojang 贴图域名获取皮肤，合成头部底层和帽子层，并缓存在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/ShitBot/inventory-head-cache/</span></span></code></pre></div><p>缓存启动时异步清理，最多保留 4096 个文件或 64 MiB。服务器无法访问 <code>textures.minecraft.net</code> 时会暂时回退到资源包里的普通玩家头图标，并在 30 秒后重试，不会阻塞 Bukkit 主线程。</p><p>格式 1、2 的历史离线快照没有玩家头贴图哈希。升级后需要让该角色上线一次、等待定时快照，或在在线状态查询一次，新的格式 3 快照才会显示自定义头。</p><h2 id="mod-和特殊渲染器边界" tabindex="-1">Mod 和特殊渲染器边界 <a class="header-anchor" href="#mod-和特殊渲染器边界" aria-label="Permalink to &quot;Mod 和特殊渲染器边界&quot;">​</a></h2><p>Forge、NeoForge 和常见混合端会尝试从 NMS/Loader 注册表反射得到真实的 <code>modid:item_name</code>，再读取 Mod JAR 的 <code>assets</code>。普通 JSON 模型可以自动显示。</p><p>以下外观由任意客户端代码或实时上下文生成，服务端通用解析器不可能仅靠资源文件完全复刻：</p><ul><li>TESR/BEWLR、ISTER、Fabric BuiltinItemRenderer 等自定义渲染器；</li><li>根据完整 NBT、能力、流体、能量或客户端状态动态改变的模型；</li><li>地图内容、旗帜、盾牌图案等需要世界或完整图案上下文的特殊模型；</li><li>自定义 OBJ/GLTF 加载器和着色器效果。</li></ul><p>这类物品使用客户端实际渲染后导出的 PNG 覆盖：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/ShitBot/item-icons/</span></span>
<span class="line"><span>├─ minecraft/diamond.png</span></span>
<span class="line"><span>├─ create/precision_mechanism.png</span></span>
<span class="line"><span>├─ example/custom_item__cmd_10001.png</span></span>
<span class="line"><span>└─ minecraft/wool__data_14.png</span></span></code></pre></div><p>找不到可用图标时才显示缺失材质占位图，并保留格子、数量和耐久信息。</p><h2 id="性能建议" tabindex="-1">性能建议 <a class="header-anchor" href="#性能建议" aria-label="Permalink to &quot;性能建议&quot;">​</a></h2><ul><li>单服默认每 60 秒写一次快照，通常无需缩短；</li><li>大型群组服可把 MySQL <code>database.async-threads</code> 调到 4-8，并按可接受的积压量设置 <code>database.maximum-queued-tasks</code>；</li><li><code>render.maximum-concurrent</code> 建议保持 2-4，<code>render.maximum-queued</code> 用于限制等待渲染的查询数量；</li><li>材质索引使用单独线程，不会和 PNG 渲染线程互相死锁；</li><li>图标缓存带资源索引代数，资源更新后旧结果自动失效；</li><li>空图标只短暂负缓存 30 秒；</li><li>图标、快照和渲染缓存均有上限，不会无限增长；</li><li>背包字段只在线程安全的时刻复制（Bukkit 主线程，Folia 上为玩家所属的区域线程）；压缩、数据库、资源扫描和图片渲染均在异步线程执行。</li></ul>`,44)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
